"""More interview Q&A: questions that were missing from the first bank (gap fill)."""
from sd_util2 import Q

QA2 = [
# Basic
Q("Basic", "Networking", "Forward proxy vs reverse proxy?",
  "A forward proxy sits in front of clients and hides them from servers (corporate proxies, VPN-like use). A reverse proxy sits in front of servers and hides them from clients (load balancing, TLS termination, caching, DDoS protection) — NGINX, Envoy, Cloudflare."),
Q("Basic", "Networking", "Polling vs long polling vs WebSockets vs SSE?",
  "Polling: ask every N seconds (simple, wasteful). Long polling: server holds the request until data arrives. WebSocket: one persistent two-way connection (chat, games). SSE: one-way server-to-client stream over HTTP (live scores, LLM token streaming)."),
Q("Basic", "Networking", "What is a webhook?",
  "A callback: your server calls a customer-registered URL when an event happens (e.g. Stripe 'payment succeeded'). Sign payloads, retry with backoff, and make receivers idempotent because deliveries can repeat."),
Q("Basic", "Fundamentals", "What are p50, p95 and p99 latency and why use p99?",
  "Percentiles of response time: p99 means 99% of requests are faster. Averages hide slow outliers; a page calling many services is as slow as its slowest call, so tail latency (p99) is what users feel."),
Q("Basic", "Fundamentals", "SLA vs SLO vs SLI?",
  "SLI is the measured indicator (e.g. % requests < 300 ms). SLO is the internal target (99.9% per month). SLA is the external contract with penalties, usually looser than the SLO."),
Q("Basic", "Caching", "What is a TTL and why add jitter to it?",
  "TTL is how long a cache entry lives before expiring. Random jitter spreads expirations so many keys don't expire at once and stampede the database (cache avalanche)."),
Q("Basic", "Caching", "CDN push vs pull?",
  "Pull: the edge fetches from the origin on the first miss and caches it (easy, most common). Push: you upload content to the CDN in advance (large, predictable files like game patches or video releases)."),
Q("Basic", "Databases", "Primary key vs unique key vs foreign key?",
  "Primary key uniquely identifies a row (one per table, not null). Unique key enforces uniqueness on other columns (e.g. email). Foreign key references another table's key to keep relationships consistent."),
Q("Basic", "Databases", "Read replicas vs sharding — what does each solve?",
  "Read replicas scale reads and improve availability but every replica holds all data and writes still go to one primary. Sharding splits the data so writes and storage scale too, at the cost of cross-shard complexity."),
Q("Basic", "APIs", "How do you version an API?",
  "Usually in the path (`/v1/...`) or a header. Never break existing clients: add optional fields, keep old versions running for a deprecation period, and document changes."),
Q("Basic", "Storage", "What is a pre-signed URL?",
  "A time-limited URL signed by your server that lets a client upload or download one object directly to/from S3 without your servers in the data path and without giving the client credentials."),
Q("Basic", "LLD", "What is an interface vs an abstract class in Java?",
  "An interface defines a contract (methods, default methods) and a class can implement many. An abstract class can hold state and constructors and a class extends only one. Use interfaces for capabilities (`PaymentGateway`), abstract classes for shared base behaviour."),
Q("Basic", "LLD", "Why must equals() and hashCode() be overridden together?",
  "HashMap/HashSet first use hashCode to find the bucket, then equals to compare. If two equal objects have different hash codes, lookups fail and duplicates appear."),
# Intermediate
Q("Intermediate", "APIs", "Which rate limiting algorithm would you choose and why?",
  "Token bucket by default: it allows short bursts up to the bucket size while enforcing an average refill rate, and needs only two numbers per key. Sliding window counter if you want smooth limits with little memory; fixed window is simplest but allows 2x bursts at window edges; sliding log is exact but memory-heavy. Store counters in Redis updated atomically (Lua) and return 429 with Retry-After."),
Q("Intermediate", "Networking", "HTTP/1.1 vs HTTP/2 vs HTTP/3?",
  "HTTP/1.1: one request at a time per connection. HTTP/2: binary, multiplexes many streams on one TCP connection, header compression. HTTP/3: runs on QUIC over UDP, avoiding TCP head-of-line blocking, faster setup, survives network changes."),
Q("Intermediate", "Networking", "How does DNS-based failover work and what limits it?",
  "Health-checked DNS records switch to a backup IP or region when the primary fails. It's limited by TTL caching in resolvers and clients, so use low TTLs (30–60 s) or Anycast/global load balancers for faster failover."),
Q("Intermediate", "Networking", "What is Anycast?",
  "Many servers in different locations announce the same IP; internet routing sends each user to the nearest one. Used by CDNs and DNS providers for low latency and DDoS absorption."),
Q("Intermediate", "Architecture", "API gateway vs load balancer?",
  "A load balancer spreads traffic across instances of a service. An API gateway is an L7 entry point for many services that adds routing by path, auth, rate limiting, transformations and aggregation; it usually sits behind or contains a load balancer."),
Q("Intermediate", "Architecture", "What is the sidecar pattern / service mesh?",
  "A helper proxy (e.g. Envoy) runs next to each service instance and handles mTLS, retries, timeouts, load balancing and telemetry. A service mesh (Istio, Linkerd) configures all sidecars centrally."),
Q("Intermediate", "Architecture", "Saga choreography vs orchestration?",
  "Choreography: services react to each other's events with no central controller — simple but the flow is implicit. Orchestration: a coordinator tells each service what to do and runs compensations — explicit, easier to monitor (Temporal, Step Functions)."),
Q("Intermediate", "Architecture", "What is a feature flag and why use one?",
  "A runtime switch that turns code paths on/off per user or percentage. It decouples deploy from release, enables gradual rollouts and A/B tests, and gives an instant kill switch."),
Q("Intermediate", "Architecture", "What is a serverless cold start?",
  "The delay when a function runs on a fresh container that must boot the runtime and load code (100 ms to seconds, worse for JVM). Mitigate with provisioned concurrency, smaller packages, SnapStart or lighter runtimes."),
Q("Intermediate", "Caching", "How do you invalidate caches when data changes in another service?",
  "Publish change events (or use CDC from the database) and have consumers delete affected keys; keep TTLs as a safety net; version keys so a new version naturally misses."),
Q("Intermediate", "Databases", "What is a write-ahead log (WAL)?",
  "An append-only log of changes written to disk before data pages are modified. It gives durability and crash recovery, and is also the source for replication and change data capture."),
Q("Intermediate", "Databases", "What is MVCC?",
  "Multi-version concurrency control: writers create new versions of rows and readers see a consistent snapshot, so readers don't block writers. Used by Postgres, MySQL InnoDB and Oracle; old versions are cleaned up later (vacuum)."),
Q("Intermediate", "Databases", "OLTP vs OLAP, and why are warehouses columnar?",
  "OLTP serves many small transactional reads/writes (app databases). OLAP runs big analytical scans and aggregations. Columnar storage reads only the needed columns and compresses well, making scans over billions of rows fast."),
Q("Intermediate", "Databases", "What is a materialised view?",
  "A stored, precomputed query result that is refreshed on a schedule or on change. It trades freshness and storage for fast reads of expensive joins/aggregations."),
Q("Intermediate", "Databases", "What is a hot partition and how do you detect it?",
  "One shard/partition receiving far more traffic than others (a celebrity, a sequential key). Detect with per-partition metrics and top-key sampling; fix with better keys, key salting, caching or splitting."),
Q("Intermediate", "Async", "How many partitions should a Kafka topic have?",
  "Enough for the target throughput and the maximum number of parallel consumers (one consumer per partition per group), with headroom since increasing partitions later changes key-to-partition mapping. Too many partitions add overhead and slower failover."),
Q("Intermediate", "Async", "What is consumer lag and why monitor it?",
  "The gap between the latest offset and what a consumer group has processed. Growing lag means consumers can't keep up; alert on it and autoscale consumers."),
Q("Intermediate", "Distributed", "What is a heartbeat and how is a failure detected?",
  "Nodes periodically send 'I'm alive' messages; missing several marks a node as suspected dead. Trade-off: short timeouts detect failures fast but cause false alarms during GC pauses or network blips (phi-accrual detectors adapt)."),
Q("Intermediate", "Distributed", "How do Snowflake IDs work?",
  "64 bits = 41-bit millisecond timestamp + 10-bit machine ID + 12-bit sequence, giving roughly time-sorted unique IDs (4,096 per ms per machine) with no coordination. Must handle clocks moving backwards."),
Q("Intermediate", "Distributed", "How long must a base62 short code be for a URL shortener?",
  "62^7 ≈ 3.5 trillion, so 7 characters cover trillions of URLs; 6 characters (≈ 57 billion) also suffice for many systems."),
Q("Intermediate", "Distributed", "Geohash vs quadtree for nearby search?",
  "Geohash encodes cells as string prefixes — easy to store in any DB/Redis; search the cell plus neighbours. Quadtree adapts cell size to density in memory — better for uneven data like drivers in cities. S2/H3 are production-grade cell systems."),
Q("Intermediate", "Distributed", "Can a Bloom filter give false negatives?",
  "No. If it says 'not present', the item was never added. It can give false positives (~1% with ~10 bits per element), and plain Bloom filters can't delete items."),
Q("Intermediate", "Reliability", "What is Little's Law and how is it used?",
  "Concurrency = throughput × latency. At 2,000 req/s and 100 ms latency you have ~200 requests in flight, which sizes thread pools, connection pools and queue capacity."),
Q("Intermediate", "Reliability", "What is chaos engineering?",
  "Deliberately injecting failures (kill instances, add latency, cut a zone) in a controlled way to prove the system degrades gracefully, e.g. Netflix Chaos Monkey."),
Q("Intermediate", "Security", "OAuth 2.0 vs OpenID Connect vs SAML?",
  "OAuth 2.0 is for delegated authorisation (access tokens to call APIs). OpenID Connect adds authentication on top (ID token: who logged in). SAML is an older XML-based SSO standard common in enterprises."),
Q("Intermediate", "Security", "RBAC vs ABAC?",
  "RBAC grants permissions through roles (admin, editor). ABAC evaluates rules on attributes of user, resource and context (department, amount, time). ABAC is more flexible but harder to manage."),
Q("Intermediate", "Security", "What are CSRF and XSS and how do you prevent them?",
  "XSS runs attacker script in your page — escape output, use CSP and HttpOnly cookies. CSRF tricks the browser into sending authenticated requests — use SameSite cookies and CSRF tokens."),
Q("Intermediate", "Patterns", "How do read receipts and 'last seen' work in chat?",
  "Clients send delivered/read acks with message sequence numbers back to the sender via the chat service; presence uses heartbeats that refresh a TTL key, and changes are pushed only to online contacts, debounced to avoid flapping."),
Q("Intermediate", "Patterns", "How does adaptive bitrate streaming work?",
  "Video is transcoded into several qualities and split into short segments listed in a manifest (HLS/DASH). The player measures bandwidth and buffer and picks the quality for each next segment."),
Q("Intermediate", "Patterns", "How does Dropbox avoid re-uploading whole files?",
  "Files are split into chunks identified by content hash; only chunks the server doesn't already have are uploaded (dedup), and a small edit changes only one chunk (delta sync)."),
Q("Intermediate", "LLD", "Strategy vs State pattern?",
  "Both swap behaviour via composition. Strategy is chosen by the client and stays fixed (pricing rule). State changes itself as the object moves through its lifecycle (vending machine Idle → HasMoney → Dispensing)."),
Q("Intermediate", "LLD", "How do you make a Singleton thread-safe in Java?",
  "Use an enum singleton or the initialization-on-demand holder idiom (a static nested class holding the instance); double-checked locking needs a volatile field. Prefer dependency injection over global singletons."),
Q("Intermediate", "LLD", "When would you use Builder, Decorator and Observer?",
  "Builder for objects with many optional parameters (readable construction, immutability). Decorator to add behaviour by wrapping without subclass explosion (Java IO streams). Observer to notify many subscribers of state changes (event listeners, notifications)."),
Q("Intermediate", "LLD", "ConcurrentHashMap vs Collections.synchronizedMap vs Hashtable?",
  "synchronizedMap and Hashtable lock the whole map for every operation. ConcurrentHashMap uses fine-grained locking/CAS so reads are mostly lock-free and writes to different bins proceed in parallel; it also offers atomic computeIfAbsent/merge."),
Q("Intermediate", "LLD", "volatile vs synchronized?",
  "volatile guarantees visibility of a variable's latest value across threads but not atomicity of compound actions. synchronized gives mutual exclusion and visibility. For counters use AtomicInteger/LongAdder."),
# Advanced
Q("Advanced", "Distributed", "Why can't you just use timestamps to order events across machines?",
  "Clocks drift and can jump (NTP adjustments), so a later event on one machine can carry an earlier timestamp than another. Use logical clocks (Lamport/vector), hybrid logical clocks, single-writer sequencing, or bounded-uncertainty clocks like TrueTime."),
Q("Advanced", "Distributed", "Linearizability vs serializability?",
  "Linearizability is a recency guarantee on single objects: once a write completes, every read sees it. Serializability is about transactions over many objects: the outcome equals some serial order. 'Strict serializability' combines both (Spanner)."),
Q("Advanced", "Distributed", "How does a sloppy quorum with hinted handoff work, and what's the downside?",
  "If home replicas are down, writes go to other healthy nodes with a hint and are handed back later. It keeps writes available but a quorum read may miss them until handoff completes, so consistency is weaker."),
Q("Advanced", "Data", "How do you build a globally unique, gap-free invoice number at scale?",
  "Gap-free sequences need serialisation: allocate per tenant/region in a single strongly consistent counter (DB sequence in a transaction) or assign numbers asynchronously after commit. If gaps are acceptable, use ranges or Snowflake IDs for scale."),
Q("Advanced", "Data", "How would you shard a social graph?",
  "Shard edges by source user ID so 'who do I follow' is one shard; keep a reverse index sharded by target for 'followers of X'. Celebrities need special handling (split follower lists, cache). Graph DBs help for multi-hop queries but are harder to scale."),
Q("Advanced", "Scale", "How do you design for exactly-once billing from a click stream?",
  "Give every click a unique ID, dedupe in the stream processor, use event-time windows with watermarks, exactly-once sinks (Kafka transactions + checkpoints, idempotent upserts), and reconcile with a daily batch recount from raw logs before invoicing."),
Q("Advanced", "Scale", "What is backpressure and how do you implement it end to end?",
  "Signalling producers to slow down when consumers fall behind: bounded queues that block or reject, reactive streams demand signalling, TCP flow control, 429/503 with Retry-After at the edge, and shedding low-priority work."),
Q("Advanced", "Scale", "How would you cut p99 latency of a service that fans out to 100 shards?",
  "Hedged requests (send a backup after the p95 delay), replicas per shard, tight per-shard timeouts with partial results, reducing fan-out (better partitioning, caching), and removing tail causes like GC pauses and noisy neighbours."),
Q("Advanced", "Reliability", "How would you perform a zero-downtime database migration from MySQL to a new datastore?",
  "Snapshot + CDC to backfill and keep the new store in sync, dual reads to compare results (shadow), switch reads behind a flag, then switch writes (or dual-write with reconciliation), keep a rollback path, and decommission after a soak period."),
Q("Advanced", "Security", "How does end-to-end encryption work in WhatsApp-like chat?",
  "Each device has key pairs; senders fetch recipients' public keys (prekeys) and run the Signal protocol (X3DH + double ratchet) to derive per-message keys. Servers only store and forward ciphertext; group chats use sender keys."),
Q("Advanced", "GenAI", "How do you reduce the cost and latency of serving an LLM?",
  "Continuous batching, KV/prompt caching for shared prefixes, quantisation and smaller distilled models, routing easy requests to cheaper models, streaming tokens (perceived latency), semantic caching, and per-tier admission control."),
Q("Advanced", "LLD", "How would you design an LLD for extensibility when requirements change mid-interview?",
  "Keep interfaces around variation points (pricing, allocation, notification channel), inject dependencies, use enums and small classes, and show the change as a new class rather than edits to existing ones (Open/Closed)."),
]
